def transform(grid):
    # The 1-filled panel is the canvas; its three colored anchors are
    # oriented to match the three isolated markers outside it.
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    if not ones:
        raise ValueError('no panel')
    r0, r1 = min(r for r, c in ones), max(r for r, c in ones)
    c0, c1 = min(c for r, c in ones), max(c for r, c in ones)
    panel = [row[c0:c1+1] for row in grid[r0:r1+1]]
    ph, pw = len(panel), len(panel[0])
    outside = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 1) and not (r0 <= r <= r1 and c0 <= c <= c1):
                outside.setdefault(v, []).append((r, c))
    if len(outside) < 3:
        raise ValueError('need three outside anchors')

    # Convert each outside anchor to its nearest corner in the anchor layout.
    points = [(v, p[0][0], p[0][1]) for v, p in outside.items()]
    er0, er1 = min(x[1] for x in points), max(x[1] for x in points)
    ec0, ec1 = min(x[2] for x in points), max(x[2] for x in points)
    target = {}
    for v, r, c in points:
        rn = (r-er0) / max(1, er1-er0)
        cn = (c-ec0) / max(1, ec1-ec0)
        corners = {'NW': (0,0), 'NE': (0,1), 'SW': (1,0), 'SE': (1,1)}
        target[v] = min(corners, key=lambda k: (rn-corners[k][0])**2 + (cn-corners[k][1])**2)

    anchors = {}
    for r in range(ph):
        for c in range(pw):
            v = panel[r][c]
            if v not in (0, 1):
                anchors.setdefault(v, (r, c))
    common = set(anchors) & set(target)
    if len(common) < 3:
        raise ValueError('panel/exterior anchors do not match')

    best, best_score = None, float('inf')
    for tr in (False, True):
        oh, ow = (pw, ph) if tr else (ph, pw)
        for fr in (False, True):
            for fc in (False, True):
                score = 0.0
                for v in common:
                    r, c = anchors[v]
                    if tr:
                        r, c = c, r
                    if fr:
                        r = oh - 1 - r
                    if fc:
                        c = ow - 1 - c
                    rn = r / max(1, oh-1)
                    cn = c / max(1, ow-1)
                    yr, yc = {'NW': (0,0), 'NE': (0,1), 'SW': (1,0), 'SE': (1,1)}[target[v]]
                    score += (rn-yr)**2 + (cn-yc)**2
                if score < best_score:
                    best_score = score
                    best = (tr, fr, fc)
    return _orient(panel, *best)
